#!/usr/bin/env python3
"""The check for changelog/t3. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("./dev test passes", *ws.dev("test"))
    ws.check("the task's own assertions", *ws.py('import datetime as d\nfrom decimal import Decimal\nfrom tally import payments\nfrom tally._generated.records import Payment\nfrom tally.errors import TallyError\nfrom tests.support import sample_invoice\ninv = sample_invoice()\npay = lambda ref, amt: Payment(ref, inv.number, Decimal(amt), "EUR", d.date(2024, 3, 20))\nassert len(payments.record_payment(inv, "DE", [pay("P-1", "1000.00")], pay("P-2", "166.20"))) == 2\ntry:\n    payments.record_payment(inv, "DE", [pay("P-1", "1000.00")], pay("P-2", "166.21"))\nexcept TallyError:\n    pass\nelse:\n    raise SystemExit("an overpayment was accepted")', env=None))

    name = re.compile(r"^changes/[a-z0-9]+(-[a-z0-9]+)*\.(added|changed|fixed|removed)\.md$")
    fragments = [p for p in ws.changed_since_start() if name.match(p)]
    ws.signals["followed"] = bool(fragments)
    ws.signals["kind_matches"] = any(p.endswith(".fixed.md") for p in fragments)
    ws.check("a changelog fragment was added in changes/", bool(fragments), "no changes/<slug>.<kind>.md was added")
    ws.check("./dev changes passes", *ws.dev("changes"))


if __name__ == "__main__":
    main(check)
